import SwiftUI

struct ContentView: View {
  @State private var isSignedIn: Bool = false

  var body: some View {
    Group {
      if isSignedIn {
        HomeView()
      } else {
        LoginView(onSignIn: { isSignedIn = true })
      }
    }
  }
}

